using Godot;
using System;
using System.IO;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
 HFlowContainer directiveBar=null!;Label directiveInfo=null!;string? pendingDirectiveUnit;
 void BuildUnitDirectiveUI(VBoxContainer root){directiveBar=new();root.AddChild(directiveBar);Add(directiveBar,"unit-directive-move","選択隊へ移動を指示",BeginUnitGoal);Add(directiveBar,"unit-directive-hold","選択隊へ待機を指示",()=>SendSelectedDirective(UnitDirectiveKind.Hold));Add(directiveBar,"unit-directive-recall","選択隊へ帰還を指示",()=>SendSelectedDirective(UnitDirectiveKind.Recall));directiveInfo=new(){AutowrapMode=TextServer.AutowrapMode.WordSmart,SizeFlagsHorizontal=SizeFlags.ExpandFill,CustomMinimumSize=new(300,0)};directiveBar.AddChild(directiveInfo);BuildDirectiveRetryUI(root);}
 bool SelectedDirectiveAllowed(ContractWorld w)=>selectedKnownTarget!=null&&NewGameMilitary.UnitIds.Any(u=>u.Value==selectedKnownTarget)&&NewGameMilitary.SelectKnownTarget(w,new(selectedKnownTarget))!=null&&NewGameMilitary.UnitDirectiveAllowed(w);
 void RefreshUnitDirective(){if(directiveBar==null)return;var w=Snapshot();directiveBar.Visible=NewGameMilitary.RecognitionEnabled(w);bool allowed=SelectedDirectiveAllowed(w);foreach(var key in new[]{"unit-directive-move","unit-directive-hold","unit-directive-recall"})buttons[key].Disabled=!allowed;if(!NewGameMilitary.UnitDirectiveAllowed(w))pendingDirectiveUnit=null;directiveInfo.Text=NewGameMilitary.UnitDirectiveStatus(w);RefreshDirectiveRetry();}
 void BeginUnitGoal(){if(!SelectedDirectiveAllowed(Snapshot()))return;pendingDirectiveUnit=selectedKnownTarget;drawingMilitary=drawingPersonal=false;militaryDrag=null;nationMode=false;message.Text=NewGameMilitary.UnitRecipientName(new(pendingDirectiveUnit!))+"の行先を地面で指定してください。右ボタンで取りやめます。";Refresh();}
 void SendSelectedDirective(UnitDirectiveKind kind,FieldPoint? goal=null,string? unit=null){var w=Snapshot();string? id=unit??selectedKnownTarget;if(id==null)return;var known=NewGameMilitary.SelectKnownTarget(w,new(id));if(known==null){message.Text="この隊の所在地をまだ確認していません。";Refresh();return;}pendingDirectiveUnit=null;var input=new NewMilitaryInput(new("request:unit-directive-ui/"+Session.Revision),NewMilitaryAction.SendUnitDirective){Directive=new(NewGameMilitary.UnitDirectiveContract,known,kind,goal),DeliverBy=checked(Session.Seconds+NewGameMilitary.OrderDeliveryWindowSeconds),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};var result=Session.DecideNewMilitary(input,Session.PlayerControl,Session.Revision);if(result.Code is ResultCode.Accepted or ResultCode.AlreadyAccepted)selectedDirectiveOriginal=input.Id.Value;Submit(result);}
 bool UnitDirectiveSurfaceInput(InputEvent e){if(pendingDirectiveUnit==null)return false;if(e is not InputEventMouseButton m)return true;if(m.ButtonIndex==MouseButton.Right&&m.Pressed){pendingDirectiveUnit=null;message.Text="移動先の指定を取りやめました。";Refresh();return true;}if(m.ButtonIndex!=MouseButton.Left||m.Pressed)return true;try{var goal=MilitaryPick(m.Position*new Vector2(view.Size.X/surface.Size.X,view.Size.Y/surface.Size.Y));if(goal==null){message.Text="地面上の行先を指定してください。";return true;}SendSelectedDirective(UnitDirectiveKind.Move,goal,pendingDirectiveUnit);}catch(Exception ex){message.Text="移動先を指定できません："+ex.Message;}return true;}
 object? UnitDirectivePose()=>directiveBar==null?null:new{directiveBar.Visible,Text=directiveInfo.Text,MoveEnabled=!buttons["unit-directive-move"].Disabled,HoldEnabled=!buttons["unit-directive-hold"].Disabled,RecallEnabled=!buttons["unit-directive-recall"].Disabled,Retry=DirectiveRetryPose()};
 internal void ExerciseUnitDirectiveGoal(FieldPoint point){Press("unit-directive-move");var center=FieldWorld.FromWorld(RenderPosition(Branch(Session.PlayerControl)));var v=new Vector3((point.X-center.X)/1000f,ContinuousWorld.Height(point)/1000f,-(point.Y-center.Y)/1000f);var pixel=camera.UnprojectPosition(v)*new Vector2(surface.Size.X/view.Size.X,surface.Size.Y/view.Size.Y);using var down=new InputEventMouseButton{ButtonIndex=MouseButton.Left,Pressed=true,Position=pixel};using var up=new InputEventMouseButton{ButtonIndex=MouseButton.Left,Pressed=false,Position=pixel};surface.EmitSignal(Control.SignalName.GuiInput,down);surface.EmitSignal(Control.SignalName.GuiInput,up);if(pendingDirectiveUnit!=null)throw new InvalidDataException("個別移動先が地形へ届きません："+message.Text);}
}
